mapper.select:
SELECT t.carrier_id AS carrierId, COUNT(1) AS tripCount, SUM(CASE WHEN t.status = #{inTransitStatus} THEN 1 ELSE 0 END) AS inTransitCount, IFNULL(SUM(t.load_tonnage), 0) AS totalTonnage, IFNULL(SUM(t.load_volume), 0) AS totalVolume, IFNULL(SUM(t.load_pieces), 0) AS totalPieces FROM biz_transport_trip t WHERE t.deleted = 0 AND t.carrier_id IN
#{cid}
GROUP BY t.carrier_id

SELECT t.berth_id AS bizId, COUNT(1) AS cnt FROM biz_transport_trip t WHERE t.deleted = 0 AND t.status = #{status} AND t.berth_id IN
#{bid}
GROUP BY t.berth_id
